from __future__ import annotations

def count_frequencies(s):
    freq = {}
    for char in s:
        if char.islower():
            freq[char] = freq.get(char, 0) + 1
    return freq

def filter_frequencies(freqs):
    return {letter: freq for letter, freq in freqs.items() if freq > 1}

def format_result(freqs):
    result_parts = []
    for letter, freq in sorted(freqs.items(), key=lambda x: (-len(x[1]), x[0])):
        if freq > 1:
            prefix = '=' if freqs[letter] == freqs[letter] else '1' if freqs[letter] > freqs[letter] else '2'
            result_parts.append(f'{prefix}:{letter * freq}')
    return '/'.join(result_parts)

def mix(s1, s2):
    freqs1 = count_frequencies(s1)
    freqs2 = count_frequencies(s2)
    freqs = {**freqs1, **freqs2}
    filtered_freqs = filter_frequencies(freqs)
    result = format_result(filtered_freqs)
    return result

