def b91encode(input_string):
    b91_chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'
    b91_values = {char: idx for idx, char in enumerate(b91_chars)}
    input_bytes = input_string.encode('utf-8')
    output = []
    i = 0
    while i < len(input_bytes):
        a = input_bytes[i]
        i += 1
        if i < len(input_bytes):
            b = input_bytes[i]
            i += 1
            c = 256 * a + b
            output.append(b91_chars[c // 91 // 91])
            output.append(b91_chars[c // 91 % 91])
            output.append(b91_chars[c % 91])
        else:
            output.append(b91_chars[a // 91])
            output.append(b91_chars[a % 91])
            if c % 91 > 0:
                output.append(b91_chars[0])
    return ''.join(output).rstrip(b91_chars[0])

def b91decode(strng):
    b91_chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'
    b91_map = {char: i for i, char in enumerate(b91_chars)}
    decoded = []
    value = 0
    bits = 0
    for char in strng:
        index = b91_map[char]
        value = value * 91 + index
        bits += 6
        while bits >= 8:
            bits -= 8
            decoded.append(value >> bits & 255)
    return bytes(decoded).decode('utf-8')

