def is_valid_number(number):
    digits = [int(d) for d in str(number)]
    return digits == sorted(digits) and sum(digits) == sum_dig

def generate_numbers(sum_dig, digs):
    if sum_dig < digs or sum_dig > 9 * digs:
        return []
    numbers = []
    for num in range(10 ** (digs - 1), 10 ** digs):
        if is_valid_number(num, sum_dig):
            numbers.append(num)
    if not numbers:
        return []
    return [len(numbers), min(numbers), max(numbers)]

def find_all(sum_dig, digs):
    numbers = generate_numbers(sum_dig, digs)
    valid_numbers = [num for num in numbers if is_valid_number(num)]
    if not valid_numbers:
        return []
    total = len(valid_numbers)
    min_num = min(valid_numbers)
    max_num = max(valid_numbers)
    return [total, min_num, max_num]

