def seconds_to_minutes(seconds):
    minutes = seconds // 60
    remainder = seconds % 60
    return (minutes, remainder)

def minutes_to_hours(minutes):
    hours = minutes // 60
    remainder = minutes % 60
    return (hours, remainder)

def hours_to_days(hours):
    return hours // 24

def format_duration(seconds):
    if seconds == 0:
        return 'now'
    years = seconds_to_minutes(seconds // 3600 // 24 // 365)
    days = seconds_to_minutes(seconds // 3600 // 24) % 365
    hours = seconds_to_minutes(seconds // 3600) % 24
    minutes = seconds_to_minutes(seconds // 60) % 60
    remaining_seconds = seconds % 60
    components = []
    if years > 0:
        components.append(f"{years} year{('s' if years > 1 else '')}")
    if days > 0:
        components.append(f"{days} day{('s' if days > 1 else '')}")
    if hours > 0:
        components.append(f"{hours} hour{('s' if hours > 1 else '')}")
    if minutes > 0:
        components.append(f"{minutes} minute{('s' if minutes > 1 else '')}")
    if remaining_seconds > 0:
        components.append(f"{remaining_seconds} second{('s' if remaining_seconds > 1 else '')}")
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f'{components[0]} and {components[1]}'
    else:
        return ', '.join(components[:-1]) + f' and {components[-1]}'

